<template>
  <div class="tc-root">
    <!-- Loading / access check spinner -->
    <div
      v-if="!accessChecked || loading"
      class="d-flex flex-column align-center justify-center"
      style="min-height: 60vh;"
    >
      <v-progress-circular
        indeterminate
        color="primary"
        size="52"
      ></v-progress-circular>
      <div class="mt-4 grey--text text--darken-1">
        {{ !accessChecked ? "Verifying access…" : "Loading training data…" }}
      </div>
    </div>

    <!-- Access denied: not HR -->
    <v-container v-else-if="!isHR" class="mt-8">
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Access Restricted</div>
            <div>
              This module is only accessible to District HR personnel. Your
              account does not have the required HR role.
            </div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-lock-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <!-- Access denied: staff not within HR's facility coverage -->
    <v-container v-else-if="!staffInCoverage" class="mt-8">
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Access Restricted</div>
            <div>
              This staff member's facility is outside your HR coverage area.
            </div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-lock-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <div v-else class="tc-form-wrap">
      <!-- ── RIGHT NAVIGATION DRAWER ──────────────────────────────────── -->
      <v-navigation-drawer
        app
        clipped
        permanent
        right
        class="primary darken-1 white--text"
        style="z-index: 3;"
      >
        <v-list class="white--text">
          <v-list-item>
            <v-btn class="secondary" dark small @click="goBack">
              <v-icon small left>mdi-close-circle-outline</v-icon>Cancel
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              :disabled="saving || !valid"
              :loading="saving"
              class="success darken-1"
              dark
              small
              @click="submitForm"
            >
              <v-icon small left>mdi-content-save</v-icon>Save
            </v-btn>
          </v-list-item>

          <v-divider color="white"></v-divider>
          <v-subheader class="white--text"><h2>Sections</h2></v-subheader>

          <v-list-item @click="scrollTo('details')">
            <v-list-item-content class="white--text">
              <v-list-item-title class="text-uppercase">
                <h4>Training Details</h4>
              </v-list-item-title>
              <v-list-item-subtitle class="white--text">
                Staff &amp; training info
              </v-list-item-subtitle>
            </v-list-item-content>
          </v-list-item>

          <v-list-item @click="scrollTo('completion')">
            <v-list-item-content class="white--text">
              <v-list-item-title class="text-uppercase">
                <h4>Completion Info</h4>
              </v-list-item-title>
              <v-list-item-subtitle class="white--text">
                Outcome &amp; certificate
              </v-list-item-subtitle>
            </v-list-item-content>
          </v-list-item>
        </v-list>
      </v-navigation-drawer>

      <v-form ref="form" v-model="valid">
        <!-- ── SECTION 1: TRAINING DETAILS ──────────────────────────── -->
        <v-card
          id="section-details"
          class="mx-auto mb-6"
          max-width="900"
          outlined
        >
          <v-card-title class="primary darken-1 white--text font-weight-bold">
            <v-icon left color="white">mdi-school</v-icon>
            Training Details
          </v-card-title>

          <v-card-text class="pa-6">
            <!-- Staff banner -->
            <div class="tc-staff-banner mb-5">
              <v-avatar color="primary darken-2" size="52" class="mr-4">
                <v-icon dark size="26">mdi-account</v-icon>
              </v-avatar>
              <div>
                <div class="subtitle-1 font-weight-bold white--text">
                  {{ staffName || "Unknown Staff" }}
                </div>
                <div class="caption" style="color: rgba(255,255,255,0.7);">
                  {{ staffPosition || "Staff Member" }}
                </div>
              </div>
            </div>

            <!-- Training info grid -->
            <v-row dense>
              <v-col cols="12" md="6" v-if="training.qualificationName">
                <div class="tc-info-block">
                  <div class="tc-info-label">COURSE/PROGRAM</div>
                  <div class="tc-info-value">
                    {{ training.qualificationName }}
                  </div>
                </div>
              </v-col>
              <v-col cols="6" md="3" v-if="training.qualificationLevel">
                <div class="tc-info-block">
                  <div class="tc-info-label">COURSE/PROGRAM LEVEL</div>
                  <div class="tc-info-value">
                    {{ training.qualificationLevel }}
                  </div>
                </div>
              </v-col>
              <v-col cols="6" md="3" v-if="training.country">
                <div class="tc-info-block">
                  <div class="tc-info-label">Country</div>
                  <div class="tc-info-value">{{ training.country }}</div>
                </div>
              </v-col>
              <v-col cols="6" md="3" v-if="training.trainingLocation">
                <div class="tc-info-block">
                  <div class="tc-info-label">Training Location</div>
                  <div class="tc-info-value">
                    {{ training.trainingLocation }}
                  </div>
                </div>
              </v-col>
              <v-col cols="12" md="6">
                <div class="tc-info-block">
                  <div class="tc-info-label">Institution</div>
                  <div class="tc-info-value">
                    {{ training.institution || "—" }}
                  </div>
                </div>
              </v-col>
              <v-col cols="6" md="4">
                <div class="tc-info-block">
                  <div class="tc-info-label">Training Type</div>
                  <v-chip small :color="typeColor" dark class="mt-1">
                    {{ training.typeDisplay || "—" }}
                  </v-chip>
                </div>
              </v-col>
              <v-col cols="6" md="4">
                <div class="tc-info-block">
                  <div class="tc-info-label">Start Date</div>
                  <div class="tc-info-value">
                    {{ formatDate(training.startDate) }}
                  </div>
                </div>
              </v-col>
              <v-col cols="6" md="4">
                <div class="tc-info-block">
                  <div class="tc-info-label">End Date</div>
                  <div class="tc-info-value">
                    {{ formatDate(training.endDate) }}
                  </div>
                </div>
              </v-col>
              <v-col cols="12" v-if="training.comments">
                <div class="tc-info-block">
                  <div class="tc-info-label">Additional Comments</div>
                  <div class="tc-info-value">{{ training.comments }}</div>
                </div>
              </v-col>
              <v-col cols="12" v-if="training.existingOutcome">
                <v-alert type="info" dense outlined class="mt-2">
                  <strong>Current status:</strong>
                  {{ outcomeLabel(training.existingOutcome) }}
                </v-alert>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>

        <!-- ── SECTION 2: COMPLETION INFO ───────────────────────────── -->
        <v-card
          id="section-completion"
          class="mx-auto mb-6"
          max-width="900"
          outlined
        >
          <v-card-title class="teal darken-1 white--text font-weight-bold">
            <v-icon left color="white">mdi-certificate</v-icon>
            Training Completion Information
          </v-card-title>

          <v-card-text class="pa-6">
            <v-row>
              <v-col cols="12">
                <v-select
                  v-model="form.outcome"
                  :items="outcomeItems"
                  label="Training Outcome *"
                  outlined
                  :rules="[rules.required]"
                  prepend-icon="mdi-flag-checkered"
                  @change="onOutcomeChange"
                ></v-select>
              </v-col>

              <template v-if="form.outcome === 'completed'">
                <v-col cols="12">
                  <v-alert type="success" dense outlined>
                    <v-icon small class="mr-1">mdi-check-circle</v-icon>
                    Please provide the completion date and certificate number
                    (if issued).
                  </v-alert>
                </v-col>

                <v-col cols="12" md="6">
                  <v-menu
                    v-model="completionDateMenu"
                    :close-on-content-click="false"
                    transition="scale-transition"
                    offset-y
                    min-width="290px"
                  >
                    <template v-slot:activator="{ on, attrs }">
                      <v-text-field
                        v-model="form.completionDate"
                        label="Completion Date *"
                        prepend-icon="mdi-calendar-check"
                        readonly
                        outlined
                        :rules="[rules.required]"
                        v-bind="attrs"
                        v-on="on"
                      ></v-text-field>
                    </template>
                    <v-date-picker
                      v-model="form.completionDate"
                      :max="today"
                      @input="completionDateMenu = false"
                    ></v-date-picker>
                  </v-menu>
                </v-col>

                <v-col cols="12" md="6">
                  <v-text-field
                    v-model="form.certificateNumber"
                    label="Certificate Number"
                    outlined
                    prepend-icon="mdi-certificate-outline"
                    hint="Leave blank if not yet issued"
                    persistent-hint
                    clearable
                  ></v-text-field>
                </v-col>
              </template>

              <template v-else-if="form.outcome === 'failed'">
                <v-col cols="12">
                  <v-alert type="warning" dense outlined>
                    <v-icon small class="mr-1">mdi-alert</v-icon>
                    The staff member failed to complete this training. No
                    certificate details are required.
                  </v-alert>
                </v-col>
              </template>

              <template v-else-if="form.outcome === 'ongoing'">
                <v-col cols="12">
                  <v-alert type="info" dense outlined>
                    <v-icon small class="mr-1">mdi-progress-clock</v-icon>
                    Training is currently ongoing. Update this record once the
                    training concludes.
                  </v-alert>
                </v-col>
              </template>
            </v-row>
          </v-card-text>
        </v-card>
      </v-form>
    </div>

    <!-- Snackbar -->
    <v-snackbar
      v-model="snackbar.show"
      :color="snackbar.color"
      top
      right
      :timeout="4000"
    >
      <v-icon left small>
        {{
          snackbar.color === "success" ? "mdi-check-circle" : "mdi-alert-circle"
        }}
      </v-icon>
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";

export default {
  name: "TrainingCompletion",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/training-completion",
      fhir: {},
      fhirId: "",
      profile: "http://ihris.org/fhir/StructureDefinition/study-leave-profile",

      valid: false,
      saving: false,
      loading: true,
      completionDateMenu: false,

      accessChecked: false,
      isHR: false,
      allowedFacilities: [],
      staffInCoverage: false,

      staffName: "",
      staffPosition: "",

      training: {
        course: "",
        institution: "",
        type: "",
        typeDisplay: "",
        startDate: "",
        endDate: "",
        country: "",
        trainingLocation: "",
        qualificationLevel: "",
        qualificationName: "",
        comments: "",
        existingOutcome: null,
      },

      form: {
        outcome: null,
        completionDate: "",
        certificateNumber: "",
      },

      // Populated at runtime from the FHIR ValueSet
      outcomeItems: [],

      rules: {
        required: (v) => !!v || "This field is required",
      },

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    today() {
      return new Date().toISOString().substr(0, 10);
    },

    typeColor() {
      const map = { longterm: "blue", shortterm: "purple", parttime: "green" };
      return map[this.training.type] || "grey";
    },
  },

  methods: {
    scrollTo(section) {
      const el = document.getElementById("section-" + section);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    goBack() {
      this.$router.go(-1);
    },

    formatDate(d) {
      if (!d) return "—";
      return new Date(d).toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    async loadOutcomeValueSet() {
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/training-outcome-valueset",
        );
        this.outcomeItems = (items || []).map((item) => ({
          text: item.display || item.code,
          value: item.code,
        }));
      } catch (err) {
        console.error("loadOutcomeValueSet error:", err);
      }
    },

    outcomeLabel(code) {
      const item = this.outcomeItems.find((i) => i.value === code);
      return item ? item.text : code;
    },

    onOutcomeChange() {
      // Completion date and certificate only apply when outcome is "completed"
      if (this.form.outcome !== "completed") {
        this.form.completionDate = "";
        this.form.certificateNumber = "";
      }
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    async checkAccess() {
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch("/site/general/getHR/" + practitionerId);
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hrList = await resp.json();

        const matched = Array.isArray(hrList)
          ? hrList.find((h) =>
              h.practitioners.find((p) => p === practitionerId),
            )
          : null;

        if (!matched) {
          this.isHR = false;
          this.accessChecked = true;
          return;
        }

        this.isHR = true;
        const coverageArr = Array.isArray(matched.coverage)
          ? matched.coverage
          : [];
        this.allowedFacilities = coverageArr.map((f) => ({
          id: f.id,
          name: f.name,
        }));
      } catch (err) {
        console.error("checkAccess error:", err);
        this.showSnackbar("Failed to verify HR access.", "error");
        this.isHR = false;
      } finally {
        this.accessChecked = true;
      }
    },

    getExt(extensions, urlPart) {
      return extensions?.find((e) => e.url.includes(urlPart));
    },

    async resolveQualificationName(exts) {
      const otherExt = exts.find((e) =>
        e.url.endsWith("/qualification-name-other"),
      );
      if (otherExt?.valueString) return otherExt.valueString;

      const nameExt = exts.find((e) => e.url.endsWith("/qualification-name"));
      if (nameExt?.valueReference?.display) {
        return nameExt.valueReference.display;
      }

      const ref = nameExt?.valueReference?.reference;
      if (!ref) return "";

      try {
        const id = ref.split("/")[1];
        const res = await fetch(`/fhir/Basic/${id}`);
        if (!res.ok) return "";
        const qualification = await res.json();
        return (
          qualification.extension?.find((e) =>
            e.url.includes("ihris-basic-name"),
          )?.valueString || ""
        );
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return "";
      }
    },

    async loadTraining(id) {
      this.loading = true;
      try {
        const res = await fetch(`/fhir/Basic/${id}`);
        const resource = await res.json();
        this.fhirId = resource.id;

        const exts = resource.extension || [];
        const getExt = (part) => exts.find((e) => e.url.includes(part));

        this.training.course = getExt("planning-course")?.valueString || "";
        this.training.institution =
          getExt("planning-institution")?.valueString || "";

        const typeCoding = getExt("training-type")?.valueCoding;
        this.training.type = typeCoding?.code || "";
        this.training.typeDisplay =
          typeCoding?.display || typeCoding?.code || "";

        const countryCoding = getExt("country")?.valueCoding;
        this.training.country =
          countryCoding?.display || countryCoding?.code || "";

        this.training.trainingLocation =
          getExt("training-location")?.valueString || "";

        const qualLevelCoding = getExt("qualification-level")?.valueCoding;
        this.training.qualificationLevel =
          qualLevelCoding?.display || qualLevelCoding?.code || "";

        this.training.comments = getExt("comments")?.valueString || "";
        this.training.qualificationName = await this.resolveQualificationName(
          exts,
        );

        // Load dates from training plan or recommendation
        const planRef = getExt("training-plan-reference")?.valueReference
          ?.reference;
        const recoRef = getExt("training-recommendation-reference")
          ?.valueReference?.reference;
        const sourceRef = planRef || recoRef;

        if (sourceRef) {
          try {
            const srcRes = await fetch(`/fhir/${sourceRef}`);
            const src = await srcRes.json();
            const srcExts = src.extension || [];
            const getSrcExt = (part) =>
              srcExts.find((e) => e.url.includes(part));
            this.training.startDate = getSrcExt("start-date")?.valueDate || "";
            this.training.endDate = getSrcExt("end-date")?.valueDate || "";
          } catch {
            // dates not critical — continue
          }
        }

        // Staff name & position come from generalMixin's practitionerProfile
        this.staffName = this.practitionerProfile.name || "";
        this.staffPosition = this.practitionerProfile.designation || "";

        // Pre-fill existing completion data
        const completionExt = exts.find((e) =>
          e.url.includes("training-completion"),
        );
        if (completionExt?.extension) {
          const cExts = completionExt.extension;
          const getCExt = (part) => cExts.find((e) => e.url.includes(part));
          const existingOutcome =
            getCExt("training-outcome")?.valueCoding?.code || null;
          this.training.existingOutcome = existingOutcome;
          this.form.outcome = existingOutcome;
          this.form.completionDate =
            getCExt("completion-date")?.valueDate || "";
          this.form.certificateNumber =
            getCExt("certificate-number")?.valueString || "";
        }
      } catch (err) {
        console.error("Error loading training:", err);
        this.showSnackbar("Failed to load training data", "error");
      } finally {
        this.loading = false;
      }
    },

    async submitForm() {
      this.$refs.form.validate();
      if (!this.valid) return;

      this.saving = true;
      try {
        this.fhir = {
          outcome: this.form.outcome,
          completionDate: this.form.completionDate || null,
          certificateNumber: this.form.certificateNumber || null,
        };
        await this.processFHIR();
        this.showSnackbar("Training completion saved successfully!", "success");
        setTimeout(() => this.goBack(), 200);
      } catch (err) {
        console.error("submitForm error:", err);
        this.showSnackbar("Failed to save. Please try again.", "error");
      } finally {
        this.saving = false;
      }
    },
  },

  async mounted() {
    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();

    if (!this.isHR) {
      this.loading = false;
      return;
    }
    this.staffInCoverage = this.allowedFacilities.some(
      (f) => String(f.id) === String(this.practitionerProfile.facility),
    );

    if (!this.staffInCoverage) {
      this.loading = false;
      return;
    }

    const id = this.queries?.id;
    if (id) {
      // Load value set and training data in parallel
      await Promise.all([this.loadOutcomeValueSet(), this.loadTraining(id)]);
    } else {
      this.loading = false;
      this.showSnackbar("No training ID provided", "error");
    }
  },
};
</script>

